#include <stdio.h>

int main(void) {
    char *row[3] = {"阿花", NULL, "小橘"};

    for (int i = 0; i < 3; i++) {
        if (row[i] == NULL) {
            printf("第 %d 张是空的\n", i);
            continue;
        }
        printf("第 %d 张 -> %s\n", i, row[i]);
    }

    return 0;
}
